import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const EnhancedAuthPage = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('');
  const navigate = useNavigate();

  const [loginForm, setLoginForm] = useState({
    email: '',
    username: '',
    password: ''
  });

  const [registerForm, setRegisterForm] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    full_name: '',
    role: 'employee',
    designation: 'associate',
    work_city: '',
    department: ''
  });

  const handleLoginChange = (e) => {
    setLoginForm({ ...loginForm, [e.target.name]: e.target.value });
  };

  const handleRegisterChange = (e) => {
    setRegisterForm({ ...registerForm, [e.target.name]: e.target.value });
  };

  const showMessage = (msg, type = 'info') => {
    setMessage(msg);
    setMessageType(type);
    setTimeout(() => {
      setMessage('');
      setMessageType('');
    }, 5000);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const loginData = loginForm.email 
        ? { email: loginForm.email, password: loginForm.password }
        : { username: loginForm.username, password: loginForm.password };

      const response = await axios.post('http://localhost:8000/login', loginData);
      
      if (response.data.access_token) {
        localStorage.setItem('token', response.data.access_token);
        localStorage.setItem('user', JSON.stringify(response.data.user_data));
        
        showMessage('Login successful! Redirecting...', 'success');
        
        setTimeout(() => {
          const userRole = response.data.user_data?.role;
          if (userRole === 'manager') {
            navigate('/team-bills');
          } else {
            navigate('/profile');
          }
        }, 1000);
      }
    } catch (error) {
      console.error('Login error:', error);
      showMessage(
        error.response?.data?.detail || 'Login failed. Please check your credentials.',
        'error'
      );
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);

    if (registerForm.password !== registerForm.confirmPassword) {
      showMessage('Passwords do not match!', 'error');
      setLoading(false);
      return;
    }

    try {
      const { confirmPassword, ...registerData } = registerForm;
      const response = await axios.post('http://localhost:8000/register', registerData);
      
      showMessage('Registration successful! Please login with your credentials.', 'success');
      setIsLogin(true);
      setRegisterForm({
        username: '',
        email: '',
        password: '',
        confirmPassword: '',
        full_name: '',
        role: 'employee',
        designation: 'associate',
        work_city: '',
        department: ''
      });
    } catch (error) {
      console.error('Registration error:', error);
      showMessage(
        error.response?.data?.detail || 'Registration failed. Please try again.',
        'error'
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-background">
        <div className="auth-pattern"></div>
      </div>
      
      <div className="auth-content">
        <div className="auth-card">
          <div className="auth-header">
            <div className="auth-logo">
              <div className="logo-icon">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M12 2L2 7L12 12L22 7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M2 17L12 22L22 17" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M2 12L12 17L22 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </div>
              <h1 className="logo-text">ExpenseTracker</h1>
            </div>
            <p className="auth-subtitle">
              {isLogin ? 'Welcome back! Please sign in to your account.' : 'Create your account to get started.'}
            </p>
          </div>

          {message && (
            <div className={`alert alert-${messageType} animate-fade-in`}>
              <div className="alert-icon">
                {messageType === 'success' && '✅'}
                {messageType === 'error' && '❌'}
                {messageType === 'info' && 'ℹ️'}
              </div>
              {message}
            </div>
          )}

          <div className="auth-tabs">
            <button
              className={`auth-tab ${isLogin ? 'active' : ''}`}
              onClick={() => setIsLogin(true)}
            >
              Sign In
            </button>
            <button
              className={`auth-tab ${!isLogin ? 'active' : ''}`}
              onClick={() => setIsLogin(false)}
            >
              Sign Up
            </button>
          </div>

          {isLogin ? (
            <form onSubmit={handleLogin} className="auth-form">
              <div className="form-group">
                <label className="form-label">Email or Username</label>
                <input
                  type="text"
                  name="email"
                  className="form-input"
                  placeholder="Enter your email or username"
                  value={loginForm.email}
                  onChange={handleLoginChange}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Password</label>
                <input
                  type="password"
                  name="password"
                  className="form-input"
                  placeholder="Enter your password"
                  value={loginForm.password}
                  onChange={handleLoginChange}
                  required
                />
              </div>

              <button
                type="submit"
                className="btn btn-primary btn-lg w-full"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <div className="loading-spinner-sm"></div>
                    Signing In...
                  </>
                ) : (
                  <>
                    <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M15 3H19C20.1046 3 21 3.89543 21 5V19C21 20.1046 20.1046 21 19 21H15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M10 17L15 12L10 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M15 12H3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                    Sign In
                  </>
                )}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="auth-form">
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Full Name</label>
                  <input
                    type="text"
                    name="full_name"
                    className="form-input"
                    placeholder="Enter your full name"
                    value={registerForm.full_name}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Username</label>
                  <input
                    type="text"
                    name="username"
                    className="form-input"
                    placeholder="Choose a username"
                    value={registerForm.username}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Email</label>
                <input
                  type="email"
                  name="email"
                  className="form-input"
                  placeholder="Enter your email address"
                  value={registerForm.email}
                  onChange={handleRegisterChange}
                  required
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Password</label>
                  <input
                    type="password"
                    name="password"
                    className="form-input"
                    placeholder="Create a password"
                    value={registerForm.password}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Confirm Password</label>
                  <input
                    type="password"
                    name="confirmPassword"
                    className="form-input"
                    placeholder="Confirm your password"
                    value={registerForm.confirmPassword}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Role</label>
                  <select
                    name="role"
                    className="form-input"
                    value={registerForm.role}
                    onChange={handleRegisterChange}
                    required
                  >
                    <option value="employee">Employee</option>
                    <option value="manager">Manager</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Designation</label>
                  <select
                    name="designation"
                    className="form-input"
                    value={registerForm.designation}
                    onChange={handleRegisterChange}
                    required
                  >
                    <option value="intern">Intern</option>
                    <option value="associate">Associate</option>
                    <option value="senior_associate">Senior Associate</option>
                    <option value="manager">Manager</option>
                    <option value="senior_manager">Senior Manager</option>
                    <option value="director">Director</option>
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Department</label>
                  <input
                    type="text"
                    name="department"
                    className="form-input"
                    placeholder="e.g., Engineering, Sales, Marketing"
                    value={registerForm.department}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Work City</label>
                  <input
                    type="text"
                    name="work_city"
                    className="form-input"
                    placeholder="e.g., Mumbai, Delhi, Bangalore"
                    value={registerForm.work_city}
                    onChange={handleRegisterChange}
                    required
                  />
                </div>
              </div>

              <button
                type="submit"
                className="btn btn-primary btn-lg w-full"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <div className="loading-spinner-sm"></div>
                    Creating Account...
                  </>
                ) : (
                  <>
                    <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M16 21V19C16 17.9391 15.5786 16.9217 14.8284 16.1716C14.0783 15.4214 13.0609 15 12 15H5C3.93913 15 2.92172 15.4214 2.17157 16.1716C1.42143 16.9217 1 17.9391 1 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <circle cx="8.5" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M20 8V14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M23 11H17" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                    Create Account
                  </>
                )}
              </button>
            </form>
          )}

          <div className="auth-footer">
            <div className="auth-divider">
              <span>Quick Access</span>
            </div>
            <div className="quick-access">
              <button
                className="btn btn-outline btn-sm"
                onClick={() => {
                  setLoginForm({ email: 'testemployee@company.com', username: '', password: 'TestPass123!' });
                  setIsLogin(true);
                }}
              >
                Demo Employee
              </button>
              <button
                className="btn btn-outline btn-sm"
                onClick={() => {
                  setLoginForm({ email: 'testmanager@company.com', username: '', password: 'TestPass123!' });
                  setIsLogin(true);
                }}
              >
                Demo Manager
              </button>
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
